Rules.InvariantScript:
Ungroup(
    Table(
        { opt: Table({ Value: "All campuses" }) },
        { opt: ForAll(Choices(Equipment_Assets.CurrentCampus) As c, { Value: c.Value }) }
    ),
    opt
)

Ungroup(
    Table(
        { opt: Table({ Value: "All rooms" }) },
        { opt: ForAll(Choices(Equipment_Assets.'CurrentLocation (CurrentLocation0)') As c, { Value: c.Value }) }
    ),
    opt
)

Ungroup(
    Table(
        { opt: Table({ Value: "All research groups" }) },
        { opt: ForAll(Choices(Equipment_Assets.OwnerGroup) As c, { Value: c.Value }) }
    ),
    opt
)

Ungroup(
    Table(
        { opt: Table({ Value: "All statuses" }) },
        { opt: ForAll(Choices(Equipment_Assets.Status) As c, { Value: c.Value }) }
    ),
    opt
)

If(
    varHomeTab = "setups",
    Set(varEditSetup, Blank());
    Navigate(scr_SetupEdit, ScreenTransition.Fade),
    Set(varEditAsset, Blank());
    Navigate(scr_AssetEdit, ScreenTransition.Fade)
)

Set(varScanCode, Trim(First(Self.Barcodes).Value));
Set(
    varScanAsset,
    LookUp(
        Equipment_Assets,
        Titel = varScanCode || SerialNumber = varScanCode || UANumber = varScanCode
    )
);
Set(varScanSetup, LookUp(Equipment_Setups, Titel = varScanCode));
If(
    !IsBlank(varScanAsset.'Id (ID)'),
    Set(varCurrentAsset, varScanAsset);
    Navigate(scr_AssetDetail, ScreenTransition.Fade),
    !IsBlank(varScanSetup.'Id (ID)'),
    Set(varCurrentSetup, varScanSetup);
    Navigate(scr_SetupDetail, ScreenTransition.Fade),
    Notify(
        "Code " & varScanCode & " not found in assets or setups.",
        NotificationType.Warning
    )
)

With(
    {
        req: Coalesce(ThisItem.CommissioningRequired.Value, "None"),
        done: Concat(ThisItem.CommissioningDone, Value, " | ")
    },
    If(
        req = "None",                       RGBA(16, 124, 16, 1),
        // Commissioned at this campus, among possibly several.
        !IsBlank(Find(req, done)),          RGBA(16, 124, 16, 1),
        // An extended commissioning covers the administrative one.
        req = "administrative"
            && !IsBlank(Find("extended", done)),
                                            RGBA(16, 124, 16, 1),
        IsBlank(done),                      RGBA(168, 0, 0, 1),
        // Something was done, but not what this asset needs.
        RGBA(196, 116, 0, 1)
    )
)
